let hero=document.getElementById("hero"),walls=document.querySelectorAll(".wall"),winner=document.querySelector(".winner"),loser=document.querySelector(".loser"),arrival=document.querySelector(".chegada"),isDragging=!1,offsetX,offsetY,posInicial={top:100,left:530},jogoAtivo=(hero.style.top=posInicial.top+"px",hero.style.left=posInicial.left+"px",!0);function colisao(e,o){e=e.getBoundingClientRect(),o=o.getBoundingClientRect();return!(e.top>o.bottom||e.bottom<o.top||e.left>o.right||e.right<o.left)}function chegada(e,o){e=e.getBoundingClientRect(),o=o.getBoundingClientRect();return!(e.top>o.bottom||e.bottom<o.top||e.left>o.right||e.right<o.left)}hero.addEventListener("mousedown",e=>{jogoAtivo&&(isDragging=!0,offsetX=e.clientX-hero.offsetLeft,offsetY=e.clientY-hero.offsetTop,hero.style.cursor="grab")}),document.addEventListener("mousemove",e=>{isDragging&&jogoAtivo&&(hero.style.left=e.clientX-offsetX+"px",hero.style.top=e.clientY-offsetY+"px",walls.forEach(e=>{colisao(hero,e)&&(jogoAtivo=!1,loser.style.display="block",hero.style.top=posInicial.top+"px",hero.style.left=posInicial.left+"px",hero.style.animation="none",isDragging=!1),chegada(hero,arrival)&&(jogoAtivo=!1,winner.style.display="block",hero.style.top=posInicial.top+"px",hero.style.left=posInicial.left+"px",hero.style.animation="none",isDragging=!1)}))}),document.addEventListener("mouseup",()=>{jogoAtivo&&(isDragging=!1,hero.style.cursor="grab")}),loser.addEventListener("click",function(){jogoAtivo=!0,loser.style.display="none"}),winner.addEventListener("click",function(){jogoAtivo=!0,winner.style.display="none"});